import { createServer } from "node:http";
import { spawn, spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join, resolve, sep, extname } from "node:path";

// Exercise the actual generated bytes and the actual deploy exclusion list,
// outside the repository. This is a local compatibility check, never a deploy.
const root = fileURLToPath(new URL("../", import.meta.url));
const evidence = resolve(process.env.WORKSPACE_EVIDENCE_DIR || join(root, "..", "..", "graph-workspace-evidence"));
// A fresh snapshot per invocation avoids stale files without deleting evidence.
const publish = join(evidence, `publish-fixture-${new Date().toISOString().replace(/[:.]/g, "-")}`);
mkdirSync(publish, { recursive: true });
const workflow = readFileSync(join(root, "..", ".github", "workflows", "s2-site-deploy.yml"), "utf8");
const assembly = workflow.split("- name: Assemble the publish directory")[1]?.split("- name: Reject absolute asset paths")[0];
if (!assembly) throw new Error("Could not find reviewed deploy assembly");
const exclusions = [...assembly.matchAll(/--exclude '([^']+)'/g)].map((m) => m[1]);
if (!exclusions.includes("vendor")) throw new Error("Deploy assembly must omit historical scroll assets");
const copy = spawnSync("rsync", ["-a", ...exclusions.map((p) => `--exclude=${p}`), `${root}/`, `${publish}/`], { encoding: "utf8" });
if (copy.status !== 0) throw new Error(`Publish assembly failed: ${copy.stderr}`);
const files = readdirSync(publish, { recursive: true }).filter((path) => statSync(join(publish, path)).isFile());
const legacy = files.filter((path) => /(?:gsap|scrolltrigger|lenis).*\.(?:js|mjs)$/i.test(path));
if (legacy.length) throw new Error(`Retired assets in publish set: ${legacy.join(", ")}`);
for (const file of ["index.html", "app.js", "data.js", "styles.css", ".htaccess",
  "intro.html", "intro.js", "intro.css", "lib/vis-network.min.js",
  "fonts/fonts.css", "fonts/inter-latin.woff2", "fonts/space-grotesk-latin.woff2"]) {
  if (!files.includes(file)) throw new Error(`Required publish asset missing: ${file}`);
}
const policy = readFileSync(join(publish, ".htaccess"), "utf8").match(/Content-Security-Policy\s+"([^"]+)"/)?.[1];
const types = { ".html": "text/html", ".js": "application/javascript", ".css": "text/css",
  ".svg": "image/svg+xml", ".woff2": "font/woff2", ".txt": "text/plain", ".json": "application/json" };
const requests = [];
const server = createServer((req, res) => {
  res.on("finish", () => requests.push({ path: req.url, status: res.statusCode }));
  try {
    const pathname = decodeURIComponent(new URL(req.url, "http://localhost").pathname);
    const path = resolve(publish, "." + (pathname === "/" ? "/index.html" : pathname));
    if (!path.startsWith(publish + sep)) { res.writeHead(403); res.end(); return; }
    const body = readFileSync(path);
    res.writeHead(200, { "content-type": types[extname(path)] || "application/octet-stream",
      "cache-control": "public, max-age=300", "x-content-type-options": "nosniff",
      "content-security-policy": policy || "default-src 'self'" });
    res.end(body);
  } catch { res.writeHead(404); res.end("Not found"); }
});
await new Promise((done) => server.listen(0, "127.0.0.1", done));
const origin = `http://127.0.0.1:${server.address().port}/`;
let exitCode = null, output = "";
try {
  const child = spawn(process.execPath, [join(root, "scripts", "smoke.mjs"), origin],
    { cwd: root, env: process.env, stdio: ["ignore", "pipe", "pipe"] });
  child.stdout.on("data", (bytes) => { output += bytes; process.stdout.write(bytes); });
  child.stderr.on("data", (bytes) => { output += bytes; process.stderr.write(bytes); });
  exitCode = await new Promise((done, reject) => { child.once("error", reject); child.once("close", done); });
} finally {
  await new Promise((done) => server.close(done));
  writeFileSync(join(evidence, "publish-smoke.log"), output);
  writeFileSync(join(evidence, "publish-smoke.json"), JSON.stringify({
    purpose: "Local generated publish-byte compatibility; not a live deployment or Apache verification",
    origin, publish, exclusions, files, requests, legacyAssets: legacy, productionCspApplied: !!policy, exitCode
  }, null, 2) + "\n");
}
if (exitCode !== 0) process.exitCode = 1;
